draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw turmeric root
  ctx.fillStyle = '#ffd700';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 150, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 50, H/2);
  ctx.stroke();

  // Draw anti-inflammatory symbols
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 - 50, 10 + 5*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 10 + 5*Math.sin(t + Math.PI), 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 + 50, 10 + 5*Math.sin(t + Math.PI/2), 0, 2*Math.PI);
  ctx.fill();

  ctx.restore();
}
